CREATE TABLE admins(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('ADMIN') DEFAULT 'ADMIN',is_active TINYINT(1) DEFAULT 1,last_login_at DATETIME NULL,created_at DATETIME DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE social_connections(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,platform VARCHAR(50) NOT NULL,account_name VARCHAR(190),account_id VARCHAR(190),page_id VARCHAR(190),channel_id VARCHAR(190),token_status ENUM('connected','expired','revoked','pending') DEFAULT 'pending',encrypted_access_token MEDIUMTEXT,encrypted_refresh_token MEDIUMTEXT,expires_at DATETIME,connected_by BIGINT UNSIGNED,metadata JSON,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX(platform)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE content_ideas(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,topic VARCHAR(255) NOT NULL,viral_hook VARCHAR(255),pillar VARCHAR(120),risk_level ENUM('low','medium','high') DEFAULT 'low',seo_keywords JSON,status VARCHAR(50) DEFAULT 'topic_ready',created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX(status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE content_packages(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,content_idea_id BIGINT UNSIGNED NOT NULL,hook VARCHAR(500),reel_script MEDIUMTEXT,youtube_short_script MEDIUMTEXT,facebook_caption MEDIUMTEXT,instagram_caption MEDIUMTEXT,tiktok_caption MEDIUMTEXT,youtube_title VARCHAR(255),youtube_description MEDIUMTEXT,linkedin_post MEDIUMTEXT,x_thread MEDIUMTEXT,whatsapp_message MEDIUMTEXT,hashtags JSON,pinned_comment MEDIUMTEXT,auto_replies JSON,thumbnail_text VARCHAR(255),image_prompts JSON,video_prompts JSON,seo_keywords JSON,safety_json JSON,risk_level VARCHAR(20),quality_score INT DEFAULT 0,status VARCHAR(60) DEFAULT 'content_generated',created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(content_idea_id) REFERENCES content_ideas(id) ON DELETE CASCADE,INDEX(status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE assets(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,content_package_id BIGINT UNSIGNED NOT NULL,asset_type VARCHAR(80),platform VARCHAR(80),size_label VARCHAR(50),width INT,height INT,file_path VARCHAR(500),file_url VARCHAR(500),status VARCHAR(40) DEFAULT 'pending',metadata JSON,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(content_package_id) REFERENCES content_packages(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE approval_queue(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,content_package_id BIGINT UNSIGNED NOT NULL,status ENUM('pending_admin_approval','approved','rejected','edit_requested') DEFAULT 'pending_admin_approval',notes MEDIUMTEXT,approved_by BIGINT UNSIGNED,approved_at DATETIME,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(content_package_id) REFERENCES content_packages(id) ON DELETE CASCADE,INDEX(status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE publishing_jobs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,content_package_id BIGINT UNSIGNED NOT NULL,platform ENUM('facebook','instagram','youtube','tiktok','whatsapp','linkedin','x') NOT NULL,status ENUM('queued','processing','published','failed') DEFAULT 'queued',scheduled_at DATETIME,published_at DATETIME,publish_url VARCHAR(500),error_text MEDIUMTEXT,metadata JSON,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(content_package_id) REFERENCES content_packages(id) ON DELETE CASCADE,INDEX(status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE analytics(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,publishing_job_id BIGINT UNSIGNED,platform VARCHAR(30),metric_date DATE,views INT DEFAULT 0,reach INT DEFAULT 0,likes INT DEFAULT 0,comments INT DEFAULT 0,shares INT DEFAULT 0,saves INT DEFAULT 0,leads INT DEFAULT 0,retention_rate DECIMAL(6,2) DEFAULT 0,created_at DATETIME DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE audit_logs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,admin_id BIGINT UNSIGNED,action VARCHAR(120),metadata JSON,ip_address VARCHAR(45),user_agent VARCHAR(255),created_at DATETIME DEFAULT CURRENT_TIMESTAMP,INDEX(action)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE settings(`key` VARCHAR(120) PRIMARY KEY,value MEDIUMTEXT NOT NULL,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
INSERT INTO settings(`key`,value) VALUES('emergency_stop','false') ON DUPLICATE KEY UPDATE value=value;
